          directory,
          ids.lost,
          'print("FMCAD_LOST_RESPONSE_ORIGINAL_JOB")',
        );
        return {
          kind: "command",
          argv,
          cwd: directory,
          timeoutMs: 180000,
          backend: cfg.backend,
          buildHash: fingerprint,
          inputFiles: inputFiles(argv, directory),
          description:
            "Observe one original job after a dropped client response",
        };
      })(),
    })

